import java.util.concurrent.*;

public class Main {
    private final CountDownLatch l2 = new CountDownLatch(1);
    private final CountDownLatch l3 = new CountDownLatch(1);

    public void first(Runnable printFirst) throws InterruptedException {
        printFirst.run();
        l2.countDown();
    }
    public void second(Runnable printSecond) throws InterruptedException {
        l2.await();
        printSecond.run();
        l3.countDown();
    }
    public void third(Runnable printThird) throws InterruptedException {
        l3.await();
        printThird.run();
    }

    public static void main(String[] a) throws Exception {
        Main m = new Main();
        Thread t1 = new Thread(() -> { try { m.first(() -> System.out.print("first")); } catch (Exception e) {} });
        Thread t2 = new Thread(() -> { try { m.second(() -> System.out.print("second")); } catch (Exception e) {} });
        Thread t3 = new Thread(() -> { try { m.third(() -> System.out.print("third")); } catch (Exception e) {} });
        t2.start(); t3.start(); t1.start();
        t1.join(); t2.join(); t3.join();
        System.out.println();
    }
}

import java.util.concurrent.*;

public class Main {
    private final Semaphore fooGate = new Semaphore(1);
    private final Semaphore barGate = new Semaphore(0);

    public void foo(Runnable printFoo) throws InterruptedException {
        for (int i = 0; i < 3; i++) {
            fooGate.acquire();
            printFoo.run();
            barGate.release();
        }
    }
    public void bar(Runnable printBar) throws InterruptedException {
        for (int i = 0; i < 3; i++) {
            barGate.acquire();
            printBar.run();
            fooGate.release();
        }
    }

    public static void main(String[] a) throws Exception {
        Main m = new Main();
        Thread tf = new Thread(() -> { try { m.foo(() -> System.out.print("foo")); } catch (Exception e) {} });
        Thread tb = new Thread(() -> { try { m.bar(() -> System.out.print("bar")); } catch (Exception e) {} });
        tf.start(); tb.start(); tf.join(); tb.join();
        System.out.println();
    }
}

import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class BoundedPool {
    private final ThreadPoolExecutor pool;

    public BoundedPool(int n, int cap) {
        AtomicInteger seq = new AtomicInteger(1);
        ThreadFactory tf = r -> new Thread(r, "bounded-pool-" + seq.getAndIncrement());
        this.pool = new ThreadPoolExecutor(n, n, 0L, TimeUnit.MILLISECONDS,
                new ArrayBlockingQueue<>(cap), tf, new ThreadPoolExecutor.CallerRunsPolicy());
    }

    public void submit(Runnable task) { pool.execute(task); }

    public String stats() {
        return "completed=" + pool.getCompletedTaskCount()
                + ", queued=" + pool.getQueue().size()
                + ", peakThreads=" + pool.getLargestPoolSize();
    }

    public int shutdownAndAwait(long timeoutSeconds) throws InterruptedException {
        pool.shutdown();
        if (pool.awaitTermination(timeoutSeconds, TimeUnit.SECONDS)) return 0;
        List<Runnable> dropped = pool.shutdownNow();
        pool.awaitTermination(5, TimeUnit.SECONDS);
        return dropped.size();
    }

    public static void main(String[] args) throws Exception {
        BoundedPool bp = new BoundedPool(2, 4);
        CountDownLatch go = new CountDownLatch(1);
        for (int i = 0; i < 10; i++) bp.submit(() -> { try { go.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } });
        System.out.println("before release: " + bp.stats());
        go.countDown();
        System.out.println("dropped on shutdown: " + bp.shutdownAndAwait(5));
        System.out.println("after  release: " + bp.stats());
    }
}
